using System;using UnityEngine;using Unity.Burst;using Unity.Jobs;using Unity.Collections;using Unity.Mathematics;
namespace FashionFit {
 public sealed class NativePanelStep:IDisposable {
  public struct Edge{public int a,b;public float length,warp,area;public bool bend;}
  public struct Box{public float3 min,max;}
  NativeArray<Vector3> positions,previous,anchors;NativeArray<int> faces;NativeArray<Edge> edges;NativeArray<float> lambda;NativeArray<Box> room;
  public NativePanelStep(Vector3[] p,int[] triangles,Edge[] links,Bounds[] boxes){positions=new NativeArray<Vector3>(p,Allocator.Persistent);previous=new NativeArray<Vector3>(p,Allocator.Persistent);anchors=new NativeArray<Vector3>(p,Allocator.Persistent);faces=new NativeArray<int>(triangles,Allocator.Persistent);edges=new NativeArray<Edge>(links,Allocator.Persistent);lambda=new NativeArray<float>(links.Length,Allocator.Persistent);room=new NativeArray<Box>(boxes.Length,Allocator.Persistent);for(int i=0;i<boxes.Length;i++)room[i]=new Box{min=boxes[i].min,max=boxes[i].max};}
  static float4x4 Matrix(Matrix4x4 m)=>new float4x4(new float4(m.m00,m.m10,m.m20,m.m30),new float4(m.m01,m.m11,m.m21,m.m31),new float4(m.m02,m.m12,m.m22,m.m32),new float4(m.m03,m.m13,m.m23,m.m33));
  public void Run(LayeredAoDai owner,Vector3[] p,Vector3[] prev,Vector3[] fixedPoints,int columns,MembraneMaterial material,float dt,int grab0,int grab1,Vector3 target0,Vector3 target1,bool onlyContact,bool front){positions.CopyFrom(p);previous.CopyFrom(prev);anchors.CopyFrom(fixedPoints);var field=owner.BodyField;var pants=owner.PantsTree;var other=front?owner.BackTree:owner.FrontTree;
   var job=new Work{p=positions,previous=previous,anchors=anchors,faces=faces,edges=edges,lambda=lambda,room=room,field=field.NativeValues,origin=field.Origin,cell=field.Cell,nx=field.X,ny=field.Y,nz=field.Z,hip=Matrix(owner.HipMatrix),inverseHip=Matrix(owner.HipMatrix.inverse),world=Matrix(owner.Avatar.transform.localToWorldMatrix),local=Matrix(owner.Avatar.transform.worldToLocalMatrix),pantsPoints=pants.Points,pantsFaces=pants.Faces,pantsOrder=pants.Order,pantsNodes=pants.Nodes,otherPoints=other.Points,otherFaces=other.Faces,otherOrder=other.Order,otherNodes=other.Nodes,columns=columns,grab0=grab0,grab1=grab1,target0=target0,target1=target1,warp=material.SheetWarp,weft=material.SheetWeft,compression=material.compressionRatio,invMass=1/(material.arealMass*.0009f),dt=dt,onlyContact=onlyContact};job.Schedule().Complete();positions.CopyTo(p);
  }
  [BurstCompile(CompileSynchronously=true,FloatMode=FloatMode.Strict)]struct Work:IJob {
   public NativeArray<Vector3> p;[ReadOnly]public NativeArray<Vector3> previous,anchors;[ReadOnly]public NativeArray<int> faces;[ReadOnly]public NativeArray<Edge> edges;public NativeArray<float> lambda;
   [ReadOnly]public NativeArray<Box> room;[ReadOnly]public NativeArray<float> field;[ReadOnly]public NativeArray<float3> pantsPoints,otherPoints;[ReadOnly]public NativeArray<int> pantsFaces,pantsOrder,otherFaces,otherOrder;[ReadOnly]public NativeArray<NativeClothTree.Node> pantsNodes,otherNodes;
   public float4x4 hip,inverseHip,world,local;public float3 origin,target0,target1;public float cell,warp,weft,compression,invMass,dt;public int nx,ny,nz,columns,grab0,grab1;public bool onlyContact;
   static float3 F(Vector3 v)=>new float3(v.x,v.y,v.z);static Vector3 V(float3 v)=>new Vector3(v.x,v.y,v.z);
   bool Fixed(int i)=>i<columns||i==grab0||i==grab1;
   public void Execute(){if(onlyContact){Project();return;}for(int i=0;i<lambda.Length;i++)lambda[i]=0;for(int iteration=0;iteration<10;iteration++){
     for(int k=0;k<edges.Length;k++){var e=edges[k];float3 d=F(p[e.b])-F(p[e.a]);float length=math.length(d);if(length<1e-7f)continue;float strain=(length-e.length)/e.length,stiffness=math.lerp(weft,warp,e.warp)*(strain<0?compression:1)*(e.bend ? .008f : 1),spring=math.max(.2f,stiffness*e.area/(e.length*e.length)),alpha=1/(spring*dt*dt),wa=Fixed(e.a)?0:invMass,wb=Fixed(e.b)?0:invMass,dl=(-(length-e.length)-alpha*lambda[k])/(wa+wb+alpha);lambda[k]+=dl;float3 correction=d*(dl/length);p[e.a]=V(F(p[e.a])-correction*wa);p[e.b]=V(F(p[e.b])+correction*wb);}
     for(int i=0;i<columns;i++)p[i]=anchors[i];if(grab0>=0)p[grab0]=V(target0);if(grab1>=0)p[grab1]=V(target1);if(iteration==4||iteration==9)Project();
    }}
   float3 Contact(float3 point,float3 old){float3 q=math.transform(hip,NativeGarmentContact.Field(math.transform(inverseHip,point),field,origin,cell,nx,ny,nz,.020f));q=NativeGarmentContact.Cloth(q,old,pantsPoints,pantsFaces,pantsOrder,pantsNodes,.012f,true);q=NativeGarmentContact.Cloth(q,old,otherPoints,otherFaces,otherOrder,otherNodes,.012f,false);float3 w=math.transform(world,q);w.y=math.max(.014f,w.y);for(int i=0;i<room.Length;i++){var b=room[i];if(math.any(w<b.min)||math.any(w>b.max))continue;float best=w.x-b.min.x;float3 result=new float3(b.min.x-.006f,w.y,w.z);float d=b.max.x-w.x;if(d<best){best=d;result=new float3(b.max.x+.006f,w.y,w.z);}d=w.y-b.min.y;if(d<best){best=d;result=new float3(w.x,b.min.y-.006f,w.z);}d=b.max.y-w.y;if(d<best){best=d;result=new float3(w.x,b.max.y+.006f,w.z);}d=w.z-b.min.z;if(d<best){best=d;result=new float3(w.x,w.y,b.min.z-.006f);}d=b.max.z-w.z;if(d<best)result=new float3(w.x,w.y,b.max.z+.006f);w=result;}return math.transform(local,w);}
   void Project(){for(int i=0;i<p.Length;i++)p[i]=V(Contact(F(p[i]),F(previous[i])));for(int pass=0;pass<3;pass++)for(int f=0;f<faces.Length;f+=3){int a=faces[f],b=faces[f+1],c=faces[f+2];float3 point=(F(p[a])+F(p[b])+F(p[c]))/3,old=(F(previous[a])+F(previous[b])+F(previous[c]))/3,d=Contact(point,old)-point;p[a]=V(F(p[a])+d);p[b]=V(F(p[b])+d);p[c]=V(F(p[c])+d);}for(int i=0;i<p.Length;i++)p[i]=V(Contact(F(p[i]),F(previous[i])));}
  }
  public void Dispose(){if(positions.IsCreated)positions.Dispose();if(previous.IsCreated)previous.Dispose();if(anchors.IsCreated)anchors.Dispose();if(faces.IsCreated)faces.Dispose();if(edges.IsCreated)edges.Dispose();if(lambda.IsCreated)lambda.Dispose();if(room.IsCreated)room.Dispose();}
 }
}
